#!/usr/bin/env python3
"""
citation_formatter.py — 法律引用格式化工具
支持 Bluebook (美国) 和中国法律引用格式

用法：
  python citation_formatter.py --file brief.txt --style bluebook
  python citation_formatter.py --file 诉状.txt --style china
  python citation_formatter.py --text "See Smith v. Jones, 123 F.3d 456 (9th Cir. 2020)." --style bluebook
"""

import re
import sys
from dataclasses import dataclass


@dataclass
class Citation:
    raw: str
    formatted: str
    style: str
    issues: list[str]


# ─── Bluebook 格式化规则 ─────────────────────────────────────

BLUEBOOK_RULES = {
    "case": {
        "pattern": r'(\w[\w\s,\.]+)\s*v\.\s*([\w\s,\.]+),\s*(\d+)\s+([\w\.]+)\s+(\d+)\s*\((.+?)\s+(\d{4})\)',
        "format": r'\1 v. \2, \3 \4 \5 (\6 \7)',
        "example": "Smith v. Jones, 123 F.3d 456 (9th Cir. 2020)",
    },
    "statute": {
        "pattern": r'(\d+)\s+U\.?S\.?C\.?\s*[§§]\s*(\d+(?:\([a-z]\))?)',
        "format": r'\1 U.S.C. § \2',
        "example": "42 U.S.C. § 1983",
    },
    "regulation": {
        "pattern": r'(\d+)\s+C\.?F\.?R\.?\s*[§§]\s*(\d+(?:\.\d+)?)',
        "format": r'\1 C.F.R. § \2',
        "example": "17 C.F.R. § 240.10b-5",
    },
}

# ─── 中国法律引用格式 ─────────────────────────────────────────

CHINA_CITATION_RULES = {
    "law": {
        "pattern": r'《([^》]+)》(?:第(\d+)条)?',
        "format": "《{name}》第{article}条",
        "example": "《民法典》第577条",
    },
    "case": {
        "pattern": r'\((\d{4})\)\s*([^号]+)号',
        "format": "（{year}）{court}号",
        "example": "（2023）最高法民终123号",
    },
    "regulation": {
        "pattern": r'《([^》]+(?:规定|办法|条例|通知|意见))》',
        "format": "《{name}》",
        "example": "《个人信息保护法》",
    },
}


def format_bluebook_citations(text: str) -> tuple[str, list[Citation]]:
    """格式化 Bluebook 引用"""
    citations = []
    result = text

    # 案例引用格式化
    case_pattern = re.compile(
        r'(\b[A-Z][a-zA-Z\s,\.]+)\s+v\.\s+([A-Z][a-zA-Z\s,\.]+),\s*(\d+)\s+([\w\.]+d?)\s+(\d+)'
        r'(?:\s*\((.+?)\s+(\d{4})\))?',
        re.MULTILINE
    )

    for match in case_pattern.finditer(text):
        raw = match.group(0)
        party1 = match.group(1).strip()
        party2 = match.group(2).strip()
        volume = match.group(3)
        reporter = match.group(4)
        page = match.group(5)
        court = match.group(6) or ""
        year = match.group(7) or ""

        # 标准化 reporter 格式
        reporter_map = {
            "F3d": "F.3d", "F2d": "F.2d", "F4th": "F.4th",
            "SCt": "S. Ct.", "US": "U.S.", "LEd": "L. Ed.",
        }
        reporter_clean = reporter_map.get(reporter.replace(".", ""), reporter)

        if court and year:
            formatted = f"{party1} v. {party2}, {volume} {reporter_clean} {page} ({court} {year})"
        else:
            formatted = f"{party1} v. {party2}, {volume} {reporter_clean} {page}"

        issues = []
        if not year:
            issues.append("缺少年份")
        if not court:
            issues.append("缺少法院/管辖区")

        citations.append(Citation(raw=raw, formatted=formatted, style="bluebook", issues=issues))

    # 法规引用格式化
    statute_pattern = re.compile(r'(\d+)\s+U\.?S\.?C\.?\s*[§§]\s*(\d+(?:\([a-z]\))*)')
    for match in statute_pattern.finditer(text):
        raw = match.group(0)
        formatted = f"{match.group(1)} U.S.C. § {match.group(2)}"
        citations.append(Citation(raw=raw, formatted=formatted, style="bluebook", issues=[]))

    return result, citations


def format_china_citations(text: str) -> tuple[str, list[Citation]]:
    """格式化中国法律引用"""
    citations = []

    # 法条引用
    law_pattern = re.compile(r'《([^》]+)》(?:\s*第\s*(\d+)\s*条)?')
    for match in law_pattern.finditer(text):
        raw = match.group(0)
        law_name = match.group(1)
        article = match.group(2)

        if article:
            formatted = f"《{law_name}》第{article}条"
        else:
            formatted = f"《{law_name}》"

        issues = []
        if not article and "法" in law_name:
            issues.append("建议明确条款号")

        citations.append(Citation(raw=raw, formatted=formatted, style="china", issues=issues))

    # 案号引用
    case_pattern = re.compile(r'[\(（](\d{4})[\)）]\s*([^\s号]{2,20}号)')
    for match in case_pattern.finditer(text):
        raw = match.group(0)
        year = match.group(1)
        case_num = match.group(2)
        formatted = f"（{year}）{case_num}"
        citations.append(Citation(raw=raw, formatted=formatted, style="china", issues=[]))

    return text, citations


def generate_citation_report(citations: list[Citation]) -> str:
    """生成引用格式化报告"""
    if not citations:
        return "未检测到需要格式化的法律引用"

    lines = [f"# 法律引用格式化报告\n共发现 {len(citations)} 处引用\n"]

    issues_count = sum(1 for c in citations if c.issues)
    if issues_count > 0:
        lines.append(f"⚠️ {issues_count} 处引用存在格式问题\n")

    lines.append("## 引用清单（原文 → 格式化后）\n")

    for i, citation in enumerate(citations, 1):
        changed = citation.raw.strip() != citation.formatted.strip()
        status = "✏️ 已修改" if changed else "✅ 格式正确"

        lines.append(f"**{i}.** {status}")
        if changed:
            lines.append(f"  - 原文: `{citation.raw.strip()}`")
            lines.append(f"  - 格式化: `{citation.formatted}`")
        else:
            lines.append(f"  - `{citation.raw.strip()}`")

        if citation.issues:
            for issue in citation.issues:
                lines.append(f"  ⚠️ {issue}")
        lines.append("")

    lines.extend([
        "---",
        "*⚠️ 所有引用需律师独立核实准确性 — ABA Formal Op. 512*"
    ])

    return "\n".join(lines)


def main():
    args = sys.argv[1:]
    file_path = None
    style = "bluebook"
    input_text = None

    i = 0
    while i < len(args):
        if args[i] == "--file" and i + 1 < len(args):
            file_path = args[i + 1]
            i += 2
        elif args[i] == "--style" and i + 1 < len(args):
            style = args[i + 1]
            i += 2
        elif args[i] == "--text" and i + 1 < len(args):
            input_text = args[i + 1]
            i += 2
        else:
            i += 1

    if not file_path and not input_text:
        print("用法: python citation_formatter.py --file <文件> --style <bluebook|china>")
        sys.exit(1)

    if file_path:
        from pathlib import Path
        for enc in ["utf-8", "gbk"]:
            try:
                input_text = Path(file_path).read_text(encoding=enc)
                break
            except (UnicodeDecodeError, FileNotFoundError):
                continue

    if style == "bluebook":
        _, citations = format_bluebook_citations(input_text)
    elif style == "china":
        _, citations = format_china_citations(input_text)
    else:
        _, citations_bb = format_bluebook_citations(input_text)
        _, citations_cn = format_china_citations(input_text)
        citations = citations_bb + citations_cn

    report = generate_citation_report(citations)
    print(report)


if __name__ == "__main__":
    main()
